#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> v;
    unordered_set<long long> seen;

    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        if (seen.insert(x).second)
            v.push_back(x);
    }

    if (v.empty()) {
        cout << 0;
        return 0;
    }

    sort(v.begin(), v.end());

    long long minDiff = v[0];
    if (v.size() >= 2) {
        minDiff = LLONG_MAX;
        for (size_t i = 1; i < v.size(); ++i)
            minDiff = min(minDiff, v[i] - v[i - 1]);
    }

    cout << minDiff * n;
    return 0;
}

